  $("#undo").on('click', function () {
    if (!hasTask()) return;

    applyUndoState(currentState-1);
  });

  $("#redo").on('click', function () {
    if (!hasTask()) return;

    applyUndoState(currentState+1);
  });

  $(document).on('keydown', function(e) {
    if (e.ctrlKey && e.key == 'z') {
      if (!hasTask()) return;

      applyUndoState(currentState-1);
      e.preventDefault();
    } else if (e.ctrlKey && e.key == 'y') {
      if (!hasTask()) return;

      applyUndoState(currentState+1);
      e.preventDefault();
    } else if (e.ctrlKey && e.key == 'a') {
      if (!hasTask()) return;

      batchSelect(true);
      e.preventDefault();
    } else if (e.key == 'Backspace' || e.key == 'Delete') {
      if (!hasTask()) return;

      batchDelete();
      e.preventDefault();
    }
  });

  loadSession();
  normalizeSession();
  setupTaskSelection();
  showTaskSelection();
  $("#loading").fadeOut({duration: 500});
});

