		}

		try {
			const appsFromMarketplace = await Apps.getAppsFromMarketplace();
			const installedApps = await Apps.getApps();

			const apps = appsFromMarketplace.map((app) => {
				const installedApp = installedApps.find(({ id }) => id === app.id);

				if (!installedApp) {
					return {
						...app,
						status: undefined,
