           relationships.category.data.id = this.categoryId;
         } else {
           selectStatus = true;
         }
         break;
       case 'sticky':
         attributes.isSticky = this.toppingRadio === 1 ? true : false;
         break;
       case 'delete':
         attributes.isDeleted = true;
         break;
       case 'marrow':
         attributes.isEssence = this.essenceRadio === 1 ? true : false;
         break;
