		pushString(withoutOuterQuotes.replace("~\"", "\""));
	}

	@Override
	public void exitFile_content_string(File_content_stringContext ctx) {
		String fileName = popString();
		String val = Utils.slurpFileOrNull(fileName);
		if (val == null) {
