     */
    @RequiresPermissions("erp:materiel:edit")
    @Log(title = "物料", businessType = BusinessType.UPDATE)
    @PostMapping("/edit")
    @ResponseBody
    public AjaxResult editSave(Materiel materiel) {
        return toAjax(materielService.updateMateriel(materiel));
    }

    /**
