    std::vector<ECS::Point> relativeCorners = {
        {relativeVision[0].x - TILESIZE, relativeVision[0].y},
        {relativeVision[0].x + TILESIZE, relativeVision[0].y},
        {relativeVision[4].x - TILESIZE, relativeVision[4].y},
        {relativeVision[4].x + TILESIZE, relativeVision[4].y}
