    {
        Reflect::Interface interface;
        try
        {
            interface = es::getInterface(proxy->iid);
        }
        catch (Exception& error)
        {
            return error.getResult();
        }
        esReport("return from upcall %p: %s::%s(",
                 esp, interface.getName().c_str(), record->method.getName().c_str());
