      stream_executor_, *literal, *device_buffer));
  TF_ASSERT_OK_AND_ASSIGN(std::unique_ptr<Literal> result,
                          transfer_manager_->TransferLiteralFromDevice(
                              stream_executor_, *device_buffer));

