func (e *evmChainInstance) deployContract(creator *ecdsa.PrivateKey, abiJSON string, bytecode []byte, args ...interface{}) *evmContractInstance {
	creatorAddress := crypto.PubkeyToAddress(creator.PublicKey)

	nonce := e.getNonce(creatorAddress)

	contractABI, err := abi.JSON(strings.NewReader(abiJSON))
	require.NoError(e.t, err)
	constructorArguments, err := contractABI.Pack("", args...)
	require.NoError(e.t, err)

	data := []byte{}
	data = append(data, bytecode...)
	data = append(data, constructorArguments...)

	value := big.NewInt(0)

	gas := e.estimateGas(ethereum.CallMsg{
		From:     creatorAddress,
		GasPrice: evm.GasPrice,
		Value:    value,
		Data:     data,
	})

	tx, err := types.SignTx(
		types.NewContractCreation(nonce, value, gas, evm.GasPrice, data),
		e.signer(),
		e.faucetKey,
	)
	require.NoError(e.t, err)

	txdata, err := tx.MarshalBinary()
	require.NoError(e.t, err)

	req, toUpload := solo.NewCallParamsOptimized(e.evmFlavor.Name, evm.FuncSendTransaction.Name, 1024,
		evm.FieldTransactionData, txdata,
	)
	req.WithIotas(gas / e.getGasPerIotas())
	for _, v := range toUpload {
		e.solo.PutBlobDataIntoRegistry(v)
	}

	_, err = e.soloChain.PostRequestSync(req, nil)
	require.NoError(e.t, err)

	return &evmContractInstance{
		chain:   e,
		creator: creator,
		address: crypto.CreateAddress(creatorAddress, nonce),
		abi:     contractABI,
	}
}

