	ret, err := e.callView(evm.FuncEstimateGas.Name, evm.FieldCallMsg, evmtypes.EncodeCallMsg(callMsg))
	if err != nil {
		e.t.Logf("%v", err)
		return evm.GasLimitDefault - 1
	}
	gas, err := codec.DecodeUint64(ret.MustGet(evm.FieldResult))
	require.NoError(e.t, err)
	return gas
}

