func (d Dispatch) checkDepth(params graphql.ResolveParams) error {
	var err error
	if d.MaxDepth > 0 {
		depth := 0
		path := params.Info.Path
		for ; path != nil && depth <= d.MaxDepth; depth++ {
			path = path.Prev
		}
		if depth > d.MaxDepth {
			err = errors.New("maximum recursion depth reached")
		}
	}
	return err
}

