// MaintainWsAuthStreamKeyFuture will keep the key alive
func (b *Binance) MaintainWsAuthStreamKeyFuture() error {
	var err error
	if listenKey == "" {
		listenKey, err = b.GetWsAuthStreamKeyFuture()
		return err
	}
	path := futureApiURL + userAccountFutureStream
