				},
			},
			expectedError:        false,
			expectedNetworkStack: provisioning.NetworkStackV6,
		},
		{
			name: "StatusDualStack",
			networkCR: &configv1.Network{
				TypeMeta: metav1.TypeMeta{
					Kind:       "Network",
