			},
			expectedError:        false,
			expectedNetworkStack: provisioning.NetworkStackDual,
		},
		{
			name: "SpecDualStack",
			networkCR: &configv1.Network{
				TypeMeta: metav1.TypeMeta{
					Kind:       "Network",
					APIVersion: "config.openshift.io/v1",
				},
				ObjectMeta: metav1.ObjectMeta{
					Name: "cluster",
