node) upsert(key Key, value interface{}) error {
	avs, err := encodeItem(key, value)
	if err != nil {
		return err
	}
	n.locker.Lock()
	defer n.locker.Unlock()
	if n.closed {
		return newErrClosed()
	}
	n.mutate(key, mutation{
		op:  opUpsert,
		avs: avs,
	})
