	// https://golang.org/pkg/regexp/syntax/
	regexStr := string(searchText)
	if a.typ >= textReplace {
		regexStr = "(?m)" + regexStr
	}
	regex, err := regexp.Compile(regexStr)
	if err != nil {
		return "", errors.Wrap(err, "unable to compile regex from action target")
	}

