                    } else {
                        vec.push(Arc::new(Mutex::new(HeapObject::Final(Value::Null))));
                    }
                }
                self.store.set(path.clone(),Arc::new(Mutex::new(HeapObject::List(vec)))).await
            }
        };
        result
    }
