        let sz = match bom.encode_to(&self.params, BgpPeer::get_message_body_ref(&mut buf)?) {
            Err(e) => return Err(e),
            Ok(sz) => sz,
        };
        self.send_message_buf(&mut sck, &mut buf, BgpMessageType::Open, sz)
            .await?;
        Ok(())
    }
