#[derive(Debug)]
pub struct PinPattern<T>
where
  T: Fetchable,
  T: std::fmt::Debug,
{
  pattern: Option<MatcherRef>,
  offset: T,
  name: String,
  custom_name: bool,
}

impl<T> PinPattern<T>
where
  T: Fetchable,
  T: 'static,
  T: std::fmt::Debug,
{
  pub fn new(pattern: Option<MatcherRef>, offset: T) -> MatcherRef {
    Rc::new(RefCell::new(Box::new(Self {
      pattern,
      offset,
      name: "Pin".to_string(),
      custom_name: false,
    })))
  }

  pub fn new_with_name(pattern: Option<MatcherRef>, name: &str, offset: T) -> MatcherRef {
    Rc::new(RefCell::new(Box::new(Self {
      pattern,
      offset,
      name: name.to_string(),
      custom_name: true,
    })))
  }

  fn _exec(
    &self,
    context: ParserContextRef,
    scope: ScopeContextRef,
  ) -> Result<MatcherSuccess, MatcherFailure> {
    let sub_context = context.borrow().clone_with_name(self.get_name());
    let offset_value_fetchable = self.offset.fetch_value(sub_context.clone(), scope.clone());
    let offset_value = match offset_value_fetchable {
      FetchableType::String(value) => value,
      FetchableType::Matcher(_) => return Err(MatcherFailure::Error(ParseError::new(
        "`Pin` matcher received another matcher as an offset... this makes no sense... aborting...",
      ))),
    };

    let offset_value_parts: Vec<&str> = offset_value.split("..").collect();

    // Set start offset
    {
      let start_offset = sub_context.borrow().offset.start;
      sub_context.borrow_mut().offset.start =
        parse_offset(start_offset, start_offset, offset_value_parts[0]);
    }

    // Set end offset (if specified)
    if offset_value_parts.len() > 1 {
      let start_offset = sub_context.borrow().offset.start;
      let end_offset = sub_context.borrow().offset.end;
      sub_context.borrow_mut().offset.end =
        parse_offset(start_offset, end_offset, offset_value_parts[1]);
    }

    let start_offset = sub_context.borrow().offset.start;
    let end_offset = sub_context.borrow().offset.end;

    match &self.pattern {
      Some(matcher) => matcher
        .borrow()
        .exec(matcher.clone(), sub_context.clone(), scope.clone()),
      None => Ok(MatcherSuccess::Token(PinToken::new_with_matched_range(
        &sub_context.borrow().parser,
        self.get_name().to_string(),
        SourceRange::new(start_offset, end_offset),
        SourceRange::new(start_offset, end_offset),
      ))),
    }
  }
}

impl<T> Matcher for PinPattern<T>
where
  T: Fetchable,
  T: 'static,
  T: std::fmt::Debug,
{
  fn exec(
    &self,
    this_matcher: MatcherRef,
    context: ParserContextRef,
    scope: ScopeContextRef,
  ) -> Result<MatcherSuccess, MatcherFailure> {
    self.before_exec(this_matcher.clone(), context.clone(), scope.clone());
    let result = self._exec(context.clone(), scope.clone());
    self.after_exec(this_matcher.clone(), context.clone(), scope.clone());

    result
  }

  fn is_consuming(&self) -> bool {
    false
  }

  fn has_custom_name(&self) -> bool {
    self.custom_name
  }

  fn get_name(&self) -> &str {
    &self.name
  }

  fn set_name(&mut self, name: &str) {
    self.name = name.to_string();
    self.custom_name = name != "Pin";
  }

  fn get_children(&self) -> Option<Vec<MatcherRef>> {
    match self.pattern {
      Some(ref matcher) => Some(vec![matcher.clone()]),
      None => None,
    }
  }

  fn add_pattern(&mut self, _: MatcherRef) {
    panic!("Can not add a pattern to a `Equals` matcher");
  }

  fn to_string(&self) -> String {
    format!("{:?}", self)
  }
}

