pub enum Mode {
    OamSearch,
    PixelTransfer,
    Hblank,
    Vblank,
}
impl Mode {
    fn working(self) -> bool {
        match self {
            Mode::OamSearch => true,
            Mode::PixelTransfer => true,
            Mode::Hblank => false,
